package com.campuseventhub;
import java.io.IOException;import java.sql.*;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/studentProfile") public class StudentProfileServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("student_id")==null){p.sendRedirect("login.jsp");return;}p.setContentType("text/html;charset=UTF-8");try(Connection c=DBConnection.getConnection();PreparedStatement x=c.prepareStatement("SELECT * FROM students WHERE student_id=?")){x.setInt(1,(Integer)s.getAttribute("student_id"));ResultSet z=x.executeQuery();if(z.next()){p.getWriter().println("<!DOCTYPE html><html><head><title>Student Profile</title><style>body{font-family:Arial;background:#f4f6f8;padding:30px}.box{max-width:550px;margin:auto;background:white;padding:30px;border-radius:12px}input{width:100%;padding:10px;margin:6px 0 12px;box-sizing:border-box}button{width:100%;padding:12px;background:#007bff;color:white;border:0;border-radius:6px}.back{display:block;text-align:center;margin-top:15px}</style></head><body><div class='box'><h1>My Profile</h1><form method='post' action='studentProfile'><label>Name</label><input name='name' value='"+esc(z.getString("name"))+"' required><label>Email</label><input value='"+esc(z.getString("email"))+"' disabled><label>Course</label><input name='course' value='"+esc(z.getString("course"))+"' required><label>Semester</label><input name='semester' value='"+esc(z.getString("semester"))+"' required><label>Phone</label><input name='phone' value='"+esc(z.getString("phone"))+"'><label>Department</label><input name='department' value='"+esc(z.getString("department"))+"'><label>New Password (leave blank to keep old)</label><input type='password' name='password'><button>Update Profile</button></form><a class='back' href='studentDashboard.jsp'>Back to Dashboard</a></div></body></html>");}}catch(Exception e){p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("student_id")==null){p.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection()){String password=r.getParameter("password");String sql=password==null||password.trim().isEmpty()?"UPDATE students SET name=?,course=?,semester=?,phone=?,department=? WHERE student_id=?":"UPDATE students SET name=?,course=?,semester=?,phone=?,department=?,password=? WHERE student_id=?";PreparedStatement x=c.prepareStatement(sql);x.setString(1,r.getParameter("name"));x.setString(2,r.getParameter("course"));x.setString(3,r.getParameter("semester"));x.setString(4,r.getParameter("phone"));x.setString(5,r.getParameter("department"));if(password==null||password.trim().isEmpty())x.setInt(6,(Integer)s.getAttribute("student_id"));else{x.setString(6,password);x.setInt(7,(Integer)s.getAttribute("student_id"));}x.executeUpdate();s.setAttribute("student_name",r.getParameter("name"));p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<script>alert('Profile updated successfully!');window.location='studentProfile';</script>");}catch(Exception e){p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}
 private String esc(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
